    void insert(EHeroAbility key, const SExpSpendUndo& v)
    {
        ++inserts;
        for (int i = 0; i < 4; ++i) if (!entries[i].used) { entries[i].used = true; entries[i].key = key; entries[i].value = v; return; }
    }
};

